def transform(grid):
    # Find seeds
    seeds = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] not in [0, 1]:
                if grid[r][c] not in seeds:
                    seeds[grid[r][c]] = (r, c)

    seed_2 = seeds.get(2, None)
    seed_3 = seeds.get(3, None)

    # Find maximal solid 1-rectangles
    def find_maximal_solid_rectangles(G):
        rows, cols = len(G), len(G[0])
        rects = []
        visited = set()

        for r in range(rows):
            for c in range(cols):
                if (r, c) in visited or G[r][c] != 1:
                    continue

                r_min, r_max = r, r
                c_min, c_max = c, c

                for cc in range(c + 1, cols):
                    if all(G[rr][cc] == 1 for rr in range(r_min, r_max + 1)):
                        c_max = cc
                    else:
                        break

                for rr in range(r + 1, rows):
                    if all(G[rr][cc] == 1 for cc in range(c_min, c_max + 1)):
